  '[data-testid="copy-turn-action-button"], button[aria-label="Copy"], button[aria-label*="Good response"], button[aria-label*="Bad response"]'
);
return { text, busy, terminal, alert, model: message ? message.dataset.messageModelSlug || '' : '' };
"#,
        )
